import{_ as a,o as i,c as n,a2 as s}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Carpentry","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/professions/carpentry.md","filePath":"es/game-design/professions/carpentry.md"}'),o={name:"es/game-design/professions/carpentry.md"};function r(l,e,t,c,d,p){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="carpentry" tabindex="-1">Carpentry <a class="header-anchor" href="#carpentry" aria-label="Enlace permanente a &quot;Carpentry&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; todas las mecánicas, ejemplos y vías de técnicas siguientes siguen siendo candidatos. <strong>Implementación:</strong> este batch documental no establece implementación de este rediseño. <strong>Disponibilidad:</strong> no establecida. <strong>Verificación:</strong> solo revisión documental; sin prueba de gameplay. <strong>Revisado:</strong> 2026-10-09 para la proyección pública; estado del diseño y mecánicas conservados de la especificación canónica.</p><p><a href="/Syrolands-Public/es/guide/professions/carpentry.html">Panorama para jugadores</a> · <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a></p><h2 id="purpose-and-profession-loop" tabindex="-1">Propósito y ciclo profesional <a class="header-anchor" href="#purpose-and-profession-loop" aria-label="Enlace permanente a &quot;Propósito y ciclo profesional&quot;">​</a></h2><p>Carpentry debería ser transformación de madera y construcción.</p><h3 id="core-chain" tabindex="-1">Cadena principal <a class="header-anchor" href="#core-chain" aria-label="Enlace permanente a &quot;Cadena principal&quot;">​</a></h3><p>Secar -&gt; Seleccionar -&gt; Cortar -&gt; Conformar -&gt; Unir -&gt; Montar -&gt; Acabar</p><h3 id="possible-concepts" tabindex="-1">Conceptos posibles <a class="header-anchor" href="#possible-concepts" aria-label="Enlace permanente a &quot;Conceptos posibles&quot;">​</a></h3><ul><li>madera verde/húmeda/curada/seca;</li><li>aserrado en vigas/tablones/tablas/espigas/astiles;</li><li>orientación de veta;</li><li>ensamblajes;</li><li>tratamientos;</li><li>acabado.</li></ul><h3 id="joinery-examples" tabindex="-1">Ejemplos de ensamblajes <a class="header-anchor" href="#joinery-examples" aria-label="Enlace permanente a &quot;Ejemplos de ensamblajes&quot;">​</a></h3><ul><li>clavijas;</li><li>espigas cilíndricas;</li><li>caja y espiga;</li><li>cola de milano;</li><li>ataduras;</li><li>clavos;</li><li>cola.</li></ul><p>No simular la carpintería con granularidad excesiva.</p><h3 id="products-and-construction" tabindex="-1">Productos y construcción <a class="header-anchor" href="#products-and-construction" aria-label="Enlace permanente a &quot;Productos y construcción&quot;">​</a></h3><ul><li>muebles;</li><li>puertas;</li><li>cofres;</li><li>carros;</li><li>cajones;</li><li>mangos de armas;</li><li>escudos;</li><li>soportes estructurales;</li><li>puentes/andamios;</li><li>estructuras de campamento;</li><li>fortificaciones;</li><li>componentes navales en alcance futuro;</li><li>componentes de arcos.</li></ul><h3 id="cross-skill" tabindex="-1">Entre habilidades <a class="header-anchor" href="#cross-skill" aria-label="Enlace permanente a &quot;Entre habilidades&quot;">​</a></h3><ul><li>Carpentry + Camping -&gt; mejores estructuras de campamento.</li><li>Carpentry + Mining -&gt; soportes de minas.</li><li>Carpentry + Tinkering -&gt; mecanismos/estructuras.</li><li>Carpentry + Blacksmithing -&gt; objetos compuestos.</li><li>Carpentry + Archery -&gt; especialización Bowmaking.</li></ul><h2 id="bowmaking-and-fletching" tabindex="-1">Bowmaking y Fletching <a class="header-anchor" href="#bowmaking-and-fletching" aria-label="Enlace permanente a &quot;Bowmaking y Fletching&quot;">​</a></h2><p>Bowmaking / Fletching es una vía de técnicas, no una habilidad independiente en esta propuesta. El catálogo existente de habilidades sigue requiriendo conciliación explícita.</p><p>Bowmaking es una especialización / vía de técnicas que surge principalmente de:</p><ul><li>Carpentry;</li><li>Archery;</li></ul><p>con apoyo opcional de Tailoring y Blacksmithing.</p><p>Un carpintero no sabe automáticamente fabricar arcos. Debe aprender Bowmaking de:</p><ul><li>un maestro;</li><li>academia;</li><li>gremio;</li><li>manuscrito;</li><li>desafío/competición;</li><li>exploración;</li><li>otro jugador cuando esté permitido.</li></ul><p>De igual modo, Luthiery puede ser después otra vía de técnicas de Carpentry.</p><p>Cadena de Bowmaking: Seleccionar madera -&gt; Secar -&gt; elegir duela -&gt; conformar -&gt; equilibrar flexión -&gt; encordar -&gt; ajustar -&gt; probar</p><p>Conceptos importantes:</p><ul><li>especie de madera;</li><li>veta;</li><li>secado;</li><li>equilibrado de flexión;</li><li>fuerza de apertura;</li><li>forma del arco;</li><li>cuerdas;</li><li>ajuste;</li><li>disparos de prueba.</li></ul><p>Familias posibles de arcos:</p><ul><li>arco corto;</li><li>arco largo;</li><li>recurvado/compuesto si ambientación/materiales los permiten.</li></ul><p>Flechas:</p><ul><li>astil;</li><li>punta;</li><li>emplumado;</li><li>montaje.</li></ul><p>Identidades posibles de flechas:</p><ul><li>ligera;</li><li>pesada;</li><li>punta ancha;</li><li>punta perforante;</li><li>roma;</li><li>variantes especializadas/alquímicas posteriores.</li></ul><p>Master Bowyer debería ser una identidad profesional valiosa que exija tiempo y conocimiento sustanciales para alcanzarse.</p><h2 id="knowledge-and-specialization" tabindex="-1">Conocimiento y especialización <a class="header-anchor" href="#knowledge-and-specialization" aria-label="Enlace permanente a &quot;Conocimiento y especialización&quot;">​</a></h2><p><strong>Woodworker&#39;s Journal.</strong> Materiales, ensamblajes, construcción y Bowmaking aprendido apoyan distintas vías profesionales. Advanced Tillering y futura Luthiery son técnicas, no capacidades automáticas ni habilidades nuevas.</p><h2 id="shared-progression-production-and-economy" tabindex="-1">Progresión, producción y economía compartidas <a class="header-anchor" href="#shared-progression-production-and-economy" aria-label="Enlace permanente a &quot;Progresión, producción y economía compartidas&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html">marco de habilidades del personaje</a> define enseñanza y dirección de límite/progreso. El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a> define descubrimiento artesanal, conocimiento compartido, dominio manual, producción por lotes, encargos y reputación multidimensional. Esas reglas no se redefinen aquí de forma independiente. La <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html">especificación de calidad</a> define los límites compartidos de resultados y las propiedades raras de objetos.</p><h2 id="related-skills-and-field-interactions" tabindex="-1">Habilidades relacionadas e interacciones en el terreno <a class="header-anchor" href="#related-skills-and-field-interactions" aria-label="Enlace permanente a &quot;Habilidades relacionadas e interacciones en el terreno&quot;">​</a></h2><p>Camping, Mining, Tinkering y Blacksmithing conectan construcción con campamentos, soportes, mecanismos y objetos compuestos. Archery contribuye a Bowmaking, con apoyo opcional de Tailoring y Blacksmithing.</p><p><a href="/Syrolands-Public/es/game-design/professions/lumberjacking.html">Lumberjacking</a> · <a href="/Syrolands-Public/es/game-design/professions/mining.html">Mining</a> · <a href="/Syrolands-Public/es/game-design/professions/tinkering.html">Tinkering</a> · <a href="/Syrolands-Public/es/game-design/professions/blacksmithing.html">Blacksmithing</a> · <a href="/Syrolands-Public/es/game-design/professions/tailoring.html">Tailoring</a> · <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">Conciliación del catálogo de habilidades</a>.</p><h2 id="abstraction-and-technical-boundary" tabindex="-1">Abstracción y límite técnico <a class="header-anchor" href="#abstraction-and-technical-boundary" aria-label="Enlace permanente a &quot;Abstracción y límite técnico&quot;">​</a></h2><p>Conservar solo estado e información que apoyen decisiones significativas. Se aplican las <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#performance-abstraction-and-authority">restricciones compartidas de abstracción/autoridad</a> y la arquitectura del mundo vivo; la persistencia requiere un diseño técnico separado. Aquí no se eligen identificadores de paquetes, esquemas, temporizadores, recursos de interfaz ni algoritmos de ejecución.</p><h2 id="open-questions" tabindex="-1">Preguntas abiertas <a class="header-anchor" href="#open-questions" aria-label="Enlace permanente a &quot;Preguntas abiertas&quot;">​</a></h2><p>Secado y almacenamiento; granularidad de ensamblajes; colocación/protección estructural; conocimiento de arcos frente a prerrequisitos de habilidad; contribución de Archery; familias de arcos/requisitos de materiales; funciones de flechas y balance de munición. La migración de lista/ID de habilidad/personajes de Bowcraft sigue sin resolverse y no está autorizada; Fletching forma parte de la vía de técnicas. Componentes navales y Luthiery siguen como alcance futuro.</p><p>El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">registro compartido de conciliación</a> define los conflictos entre sistemas. Los experimentos y la evidencia de combate existentes no validan este rediseño de profesiones.</p><h2 id="proposed-training-facilities-—-batch-05" tabindex="-1">Instalaciones de entrenamiento en estado Propuesto — Batch 05 <a class="header-anchor" href="#proposed-training-facilities-—-batch-05" aria-label="Enlace permanente a &quot;Instalaciones de entrenamiento en estado Propuesto — Batch 05&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/characters/familiarity.html#training-facilities-and-crafts">Familiarity e instalaciones compartidas</a> considera muñecos fabricados, blancos articulados/móviles, mecanismos de campo de tiro y focos de práctica mágica, con Carpentry, Tinkering e Inscription como posibles participantes. Aquí no se asignan funciones/recetas. Las instalaciones deberían mantener eficientemente la fluidez, no convertirse en el método óptimo de repetición para subir habilidades básicas ni eludir el descubrimiento.</p>',48)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
